package org.apache.commons.compress.archivers.zip;

import org.junit.jupiter.api.Test;
import java.io.IOException;
import static org.junit.jupiter.api.Assertions.*;

class RandomAccessOutputStreamTest {

    private static class MockRandomAccessOutputStream extends RandomAccessOutputStream {
        private long position = 0;
        private byte[] buffer = new byte[1024];

        @Override
        public long position() {
            return position;
        }

        @Override
        public void writeFullyAt(byte[] b, int off, int len, long position) {
            System.arraycopy(b, off, buffer, (int) position, len);
            this.position = position + len;
        }

        @Override
        public void write(int b) {
            buffer[(int) position] = (byte) b;
            position++;
        }
    }

    @Test
    void testPosition() throws IOException {
        MockRandomAccessOutputStream stream = new MockRandomAccessOutputStream();
        assertEquals(0, stream.position());
        stream.write(1);
        assertEquals(1, stream.position());
    }

    @Test
    void testWriteFullyAt() throws IOException {
        MockRandomAccessOutputStream stream = new MockRandomAccessOutputStream();
        byte[] data = {1, 2, 3, 4};
        stream.writeFullyAt(data, 0);
        assertEquals(4, stream.position());
    }

    @Test
    void testWriteFullyAtWithOffsetAndLength() throws IOException {
        MockRandomAccessOutputStream stream = new MockRandomAccessOutputStream();
        byte[] data = {1, 2, 3, 4, 5, 6};
        stream.writeFullyAt(data, 2, 3, 0);
        assertEquals(3, stream.position());
    }

    @Test
    void testWriteInt() throws IOException {
        MockRandomAccessOutputStream stream = new MockRandomAccessOutputStream();
        stream.write(255);
        assertEquals(1, stream.position());
    }
}

package org.apache.commons.compress.archivers.zip;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.SeekableByteChannel;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

class SeekableChannelRandomAccessOutputStreamTest {

    private SeekableByteChannel mockChannel;
    private SeekableChannelRandomAccessOutputStream outputStream;

    @BeforeEach
    void setUp() {
        mockChannel = Mockito.mock(SeekableByteChannel.class);
        outputStream = new SeekableChannelRandomAccessOutputStream(mockChannel);
    }

    @Test
    void testWrite() throws IOException {
        byte[] data = {1, 2, 3, 4};
        outputStream.write(data, 0, data.length);

        verify(mockChannel, times(1)).write(any(ByteBuffer.class));
    }

    @Test
    void testPosition() throws IOException {
        when(mockChannel.position()).thenReturn(10L);

        long position = outputStream.position();

        assertEquals(10L, position);
        verify(mockChannel, times(1)).position();
    }

    @Test
    void testWriteFullyAt() throws IOException {
        byte[] data = {1, 2, 3, 4};
        long position = 5L;
        when(mockChannel.position()).thenReturn(0L);

        outputStream.writeFullyAt(data, 0, data.length, position);

        verify(mockChannel, times(1)).position(position);
        verify(mockChannel, times(1)).write(any(ByteBuffer.class));
        verify(mockChannel, times(1)).position(0L);
    }

    @Test
    void testClose() throws IOException {
        outputStream.close();

        verify(mockChannel, times(1)).close();
    }
}

