        assertNotNull(fileTime);
        assertEquals(1000L, fileTime.toMillis());
    }

    @Test
    public void testGetCreateFileTime() {
        X5455_ExtendedTimestamp xf = new X5455_ExtendedTimestamp();
        xf.setCreateJavaTime(new Date(1000L));
