            /* zip64 end of central dir        */
            /* signature                       */ WORD
            /* size of zip64 end of central    */
            /* directory record                */ + DWORD
            /* version made by                 */ + SHORT
            /* version needed to extract       */ + SHORT
            /* number of this disk             */ + WORD;

