            0, 1, 7, 6, 8, 2, 3, 5, 4
    };
    private static final byte[] FIXTURE2 = {
            'C', 'o', 'm', 'm', 'o', 'n', 's', ' ', 'C', 'o', 'm', 'p', 'r', 'e', 's', 's',
    };
    private static final byte[] FIXTURE2_BWT = {
            's', 's', ' ', 'r', 'o', 'm', 'o', 'o', 'C', 'C', 'm', 'm', 'p', 'n', 's', 'e',
    };

    @Test
