    private int[] getInts(final CPClass[] cpClasses) {
        final int[] ints = new int[cpClasses.length];
        for (int i = 0; i < ints.length; i++) {
            if (cpClasses[i] != null) {
                ints[i] = cpClasses[i].getIndex();
            }
        }
        return ints;
    }

