    public ZipArchiveOutputStream(final SeekableByteChannel channel) throws IOException {
        this.channel = channel;
        def = new Deflater(level, true);
        streamCompressor = StreamCompressor.create(channel, def);
        out = null;
        isSplitZip = false;
    }

