package org.apache.commons.compress.archivers.cpio;

import static org.junit.Assert.*;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.InputStream;
import org.apache.commons.compress.AbstractTestCase;
import org.apache.commons.compress.utils.IOUtils;
import org.junit.Test;

public class CpioArchiveOutputStreamTest2 extends AbstractTestCase {

    @Test
    public void testEntryFormatDocumentation() throws Exception {
        final File f = getFile("test1.xml");
        final File output = new File(dir, "test.cpio");
        final FileOutputStream out = new FileOutputStream(output);
        InputStream in = null;
        try {
            final CpioArchiveOutputStream os =
                new CpioArchiveOutputStream(out, CpioConstants.FORMAT_NEW);
            os.putArchiveEntry(new CpioArchiveEntry(CpioConstants.FORMAT_NEW, f, "test1.xml"));
            IOUtils.copy(in = new FileInputStream(f), os);
            in.close();
            in = null;
            os.closeArchiveEntry();
            os.close();
        } finally {
            if (in != null) {
                in.close();
            }
            out.close();
        }
        try {
            in = new CpioArchiveInputStream(new FileInputStream(output));
            final CpioArchiveEntry e = ((CpioArchiveInputStream) in).getNextCPIOEntry();
            assertEquals("test1.xml", e.getName());
            assertNull(((CpioArchiveInputStream) in).getNextEntry());
        } finally {
            if (in != null) {
                in.close();
            }
        }
    }
}

